(self.webpackChunkroot=self.webpackChunkroot||[]).push([[3792,6025],{"./stories/12.Sunburst/NightingaleSunburst.mdx"(__unused_webpack_module,__webpack_exports__,__webpack_require__){"use strict";__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{default:()=>MDXContent});__webpack_require__("./node_modules/react/index.js");var jsx_runtime=__webpack_require__("./node_modules/react/jsx-runtime.js"),mdx_react_shim=__webpack_require__("./node_modules/@storybook/addon-docs/dist/shims/mdx-react-shim.mjs"),dist=__webpack_require__("./node_modules/@storybook/blocks/dist/index.mjs");var nightingale_base_element=__webpack_require__("./packages/nightingale-new-core/src/nightingale-base-element.md"),README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withDimensions/README.md"),withHighlight_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withHighlight/README.md"),withMargin_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withMargin/README.md"),withPosition_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withPosition/README.md");function _createMdxContent(props){const _components={p:"p",...(0,mdx_react_shim.useMDXComponents)(),...props.components};return(0,jsx_runtime.jsxs)(jsx_runtime.Fragment,{children:[(0,jsx_runtime.jsx)(dist.Meta,{title:"Components/Other/Sunburst/Readme"}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:'# nightingale-sunburst\n\n[![Published on NPM](https://img.shields.io/npm/v/@nightingale-elements/nightingale-sunburst.svg)](https://www.npmjs.com/package/@nightingale-elements/nightingale-sunburst)\n\nA custom element that creates a sunburst visualization for a taxonomy tree.\n\n## Usage\n\n```html\n<nightingale-sunburst\n  id="sunburst"\n  side="600"\n  weight-attribute="numSequences"\n  name-attribute="node"\n  max-depth="7"\n  font-size="10"\n  show-tooltip\n></nightingale-sunburst>\n```\n\n## API reference\n\n### Attributes\n\n#### `side: number (default: 500)`\n\nThis will be used as `width` and `height` of the canvas and as the diameter of the biggest circle in the sunburst.\n\n#### `weight-attribute: string (default: "value")`\n\nThe attribute in the `data` nodes that will be used to calculate the proportions of the segments in the sunburst.\n\nNote: All the nodes in the `data` parameter should have an attribute named as indicated in this attribute.\n\n#### `name-attribute: string (default: "name")`\n\nThe attribute in the `data` nodes that will be used to for the labels of each segment.\n\nNote: All the nodes in the `data` parameter should have an attribute named as indicated in this attribute.\n\n#### `id-attribute: string (default: "id")`\n\nThe attribute in the `data` nodes that will be used as a unique ID for each node.\n\nNote: All the nodes in the `data` parameter should have an attribute named as indicated in this attribute.\n\n#### `max-depth: number (default: Infinity)`\n\nThe number of levels that the sunburst tree will be displayed.\nIf not included the component will go through the whole hierarchy.\n\n#### `font-size: number (default: 10)`\n\nFont size for the labels drawn over the segments.\n\n#### `show-tooltip: boolean (default: false)`\n\nIf `true` the canvas will include a tooltip on the top-left corner with the information of the current segment. The current segment is the last one the user clicked on, or if none, it would be the segment where the mouse is hovering.\n\n#### `weight-attribute-label: string (default: \'Value\')`\n\nLabel to show in the labels. Only relevant if `show-tooltip` is `true`\n\n### Properties\n\n#### `data: Object`\n\nThe hierarchy that will be represented in the sunburst. It should be an object representing the root `Node` with an attribute `children` as an array of other `Node` objects.\n\n- Each `Node` should have a unique identifier in the property indicated in the attribute `id-attribute`.\n- Each `Node` should have a name tag in the property indicated in the attribute `name-attribute`, used to generate the labels.\n- Each `Node` should have a numerical value in the property indicated in the attribute `weight-attribute` representing the weight of that node in the tree.\n\n#### `activeSegment: Node` **_[Read-Only]_**\n\nThe `Node` of the segment that is currently hovered, or which has been clicked lastly.\n\n#### `holdSegment: Boolean` **_[Read-Only]_**\n\nIndicates if the `activeSegment` is being held from a recent click, and therefore is ignoring any other segment that has been currently hovered.\n\n##### `topOptions Array<String>`\n\nThe list of options used on the first level of the sunburst, which define the color of its children segments.\n\ndefault: `["bacteria", "viruses", "archaea", "eukaryota", null]`\n\n### Methods\n\n##### `getColorBySuperKingdom(name: String): String`\n\nReturns a string representing the RGB color that is used for the given superkingdom string or any of its children.\n\n##### `renderCanvas(): void`\n\nYou can use this method to manually trigger a render of the canvas.\n\n### Events\n\n##### `taxon-hover`\n\nIs dispatched when a segment is hovered or clicked onto. It includes the `activeSegment` data as its `detail`\n\nUsage example:\n\n```js\nsunburstElement.addEventListener("taxon-hover", (evt) => {\n  console.log(evt.detail);\n});\n```\n\n### Other attributes and parameters\n\nThis comoponent inherits from [LitElement](https://lit.dev/docs/api/LitElement/) and therefore all the methods and properties from LitElements are also available here.\n'}),"\n",(0,jsx_runtime.jsx)("hr",{}),"\n",(0,jsx_runtime.jsx)("h2",{children:"Mixins"}),"\n",(0,jsx_runtime.jsx)("p",{children:(0,jsx_runtime.jsx)(_components.p,{children:"This component implement the following mixins, and therefore it includes their\nattributes and properties."})}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withHighlight_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withMargin_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withPosition_README}),"\n",(0,jsx_runtime.jsx)("h2",{children:"Parent Class"}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:nightingale_base_element})]})}function MDXContent(props={}){const{wrapper:MDXLayout}={...(0,mdx_react_shim.useMDXComponents)(),...props.components};return MDXLayout?(0,jsx_runtime.jsx)(MDXLayout,{...props,children:(0,jsx_runtime.jsx)(_createMdxContent,{...props})}):_createMdxContent(props)}},"./node_modules/@storybook/addon-docs/dist/shims/mdx-react-shim.mjs"(__unused_webpack_module,__webpack_exports__,__webpack_require__){"use strict";__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{MDXProvider:()=>_mdx_js_react__WEBPACK_IMPORTED_MODULE_0__.MDXProvider,useMDXComponents:()=>_mdx_js_react__WEBPACK_IMPORTED_MODULE_0__.useMDXComponents});var _mdx_js_react__WEBPACK_IMPORTED_MODULE_0__=__webpack_require__("./node_modules/@storybook/addon-docs/node_modules/@mdx-js/react/index.js")},"./node_modules/@storybook/addon-docs/node_modules/@mdx-js/react/index.js"(__unused_webpack_module,__webpack_exports__,__webpack_require__){"use strict";__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{MDXProvider:()=>MDXProvider,useMDXComponents:()=>useMDXComponents});var react=__webpack_require__("./node_modules/react/index.js");const emptyComponents={},MDXContext=react.createContext(emptyComponents);function useMDXComponents(components){const contextComponents=react.useContext(MDXContext);return react.useMemo(function(){return"function"==typeof components?components(contextComponents):{...contextComponents,...components}},[contextComponents,components])}function MDXProvider(properties){let allComponents;return allComponents=properties.disableParentContext?"function"==typeof properties.components?properties.components(emptyComponents):properties.components||emptyComponents:useMDXComponents(properties.components),react.createElement(MDXContext.Provider,{value:allComponents},properties.children)}},"./node_modules/@storybook/blocks/dist sync recursive"(module){function webpackEmptyContext(req){var e=new Error("Cannot find module '"+req+"'");throw e.code="MODULE_NOT_FOUND",e}webpackEmptyContext.keys=()=>[],webpackEmptyContext.resolve=webpackEmptyContext,webpackEmptyContext.id="./node_modules/@storybook/blocks/dist sync recursive",module.exports=webpackEmptyContext},"./node_modules/@storybook/core/dist/components sync recursive"(module){function webpackEmptyContext(req){var e=new Error("Cannot find module '"+req+"'");throw e.code="MODULE_NOT_FOUND",e}webpackEmptyContext.keys=()=>[],webpackEmptyContext.resolve=webpackEmptyContext,webpackEmptyContext.id="./node_modules/@storybook/core/dist/components sync recursive",module.exports=webpackEmptyContext},"./node_modules/@storybook/core/dist/theming sync recursive"(module){function webpackEmptyContext(req){var e=new Error("Cannot find module '"+req+"'");throw e.code="MODULE_NOT_FOUND",e}webpackEmptyContext.keys=()=>[],webpackEmptyContext.resolve=webpackEmptyContext,webpackEmptyContext.id="./node_modules/@storybook/core/dist/theming sync recursive",module.exports=webpackEmptyContext},"./packages/nightingale-new-core/src/mixins/withDimensions/README.md"(module){"use strict";module.exports="### withDimensions\n\nIt adds `width` and `height` as parameters.\n\n##### Options\n\nWhen instancing this mixin, the function can receive an object with options for default values:\n\n```javascript\n{\n  width?: number;\n  height?: number;\n}\n```\n\n##### Attributes\n\n###### `height: number (default undefined)`\n\nThe height of the track as a numeric value in pixels.\n\n###### `width: number (default undefined)`\n\nThe width of the track as a numeric value in pixels.\n"},"./packages/nightingale-new-core/src/mixins/withHighlight/README.md"(module){"use strict";module.exports="### withHighlight\n\nIt adds the necessary properties to a component that is using highlight. Notice, this doesn't render the anything in your component. Rather it takes care of setting the parameters and react when they changes.\n\nA component that wants to render a highlight needs to implement the `updateHighlight` method which will be called when the highlight attribute is updated.\n\nIt adds `highlight` and `highlight-color` as attributes.\n\n##### Attributes\n\n###### `highlight: string | null (default null)`\n\nA string representing a set of regions that required to be highilghted. it is a comma separated list of regions and each region, has start and end separated by `:`.\n\nFor example, `1:5,10:20` represents 2 regions. The first region goes from position `1` to `5`, and the second region goes from `10` to `20`.\n\n`null` represents no region needs to be highlighted.\n\n###### `highlight-color: string (default #FFEB3B66)`\n\nThe color to use when rendering the highlight. It follows the web standard defined in https://developer.mozilla.org/en-US/docs/Web/CSS/color_value\n\n##### Properties\n\n###### `fixedHighlight: string | null (default null)`\n\nWorks similar to the `highlight` attribute. The idea is to have a way to define a region that is always highlighted independently of the changes of `highlight`. Used in interpro to highlight the coverage of a chain in a protein.\n\n##### Methods\n\n###### ` protected updateHighlight()`\n\nThis method is called when any the highlight regions changed. In this mixin is just a place holder, but a component using `withHighlight` is expected to implement the highlight rendering logic by overwriting this method.\n"},"./packages/nightingale-new-core/src/mixins/withMargin/README.md"(module){"use strict";module.exports="### withMargin\n\nDefines attributes for the margin of the component. it has a helper method to render the margins on a given d3 selection; this method is not automatically called, and it's the component resposability to invoke it at the right time.\n\n##### Mixins\n\nImplements the mixin `withDimensions` to be able to calculate values with `width` and `height`.\n\n##### Attributes\n\n###### `margin-top: number (default: 0)`\n\nTop margin in pixels\n\n###### `margin-bottom: number (default: 0)`\n\nBottom margin in pixels\n\n###### `margin-left: number (default: 10)`\n\nLeft margin in pixels\n\n###### `margin-right: number (default: 10)`\n\nRight margin in pixels\n\n###### `margin-color?: string | null (default: #FFFFFFDD)`\n\nThe color to use when rendering the margin. It follows the web standard defined in https://developer.mozilla.org/en-US/docs/Web/CSS/color_value\n\n##### Methods\n\n###### `getWidthWithMargins(): number`\n\nSubstract the defined margins(left and right) from the width.\n\n###### `getHeightWithMargins()`\n\nSubstract the defined margins(top and bottom) from the height.\n\n###### `renderMarginOnGroup( g?: Selection<SVGGElement, unknown, HTMLElement | SVGElement | null, unknown>): void`\n\nGiven a D3 selection it renders rectangles in the position of the margins, filling them with `margin-color`\n"},"./packages/nightingale-new-core/src/mixins/withPosition/README.md"(module){"use strict";module.exports="### withPosition\n\nAdds the attributes required for the position to locate the track.\n\n##### Attributes\n\n###### `display-start?: number (default 1)`\n\nPosition on the sequence where the track should start rendering from.\n\n###### `display-end?: number (default -1)`\n\nPosition on the sequence where the track should end its rendering. The default `-1` represents the end of the sequence.\n\n###### `length?: number (default 0)`\n\nLength of the sequence\n"},"./packages/nightingale-new-core/src/nightingale-base-element.md"(module){"use strict";module.exports="### NightingaleElement\n\nThe base element for any Nightingale component. Inherits from [LitElement](https://lit.dev/docs/api/LitElement/).\n\nAny logic that should be shared for all the components should be included here. Currently the only thing is doing, is setting the render root of the components in the element itself, instead of shadowDOM, the Lit element default.\n"}}]);
